// Array NEW[] and DELETE[] operators
Widget* pa = new Widget[10];     // Allocate array of 10 Widgets
delete[] pa;                     // Deallocate array (calls 10 destructors)

// What new[] does internally:
Widget* pa = new Widget[10];
// Approximately expands to:
void* raw = operator new[](sizeof(Widget) * 10 + overhead);  // Allocate with size metadata
size_t* size_ptr = static_cast<size_t*>(raw);
*size_ptr = 10;                           // Store array size (implementation-defined)
Widget* pa = reinterpret_cast<Widget*>(size_ptr + 1);
for (size_t i = 0; i < 10; ++i) {
  new (&pa[i]) Widget();                  // Construct each element
}

// What delete[] does internally:
delete[] pa;
// Approximately expands to:
if (pa != nullptr) {
  size_t* size_ptr = reinterpret_cast<size_t*>(pa) - 1;
  size_t count = *size_ptr;               // Read array size
  for (size_t i = count; i > 0; --i) {
    pa[i-1].~Widget();                    // Destruct in reverse order
  }
  operator delete[](size_ptr);            // Deallocate with original pointer
}

// Custom array allocation/deallocation
void* operator new[](size_t size);              // Array allocator
void operator delete[](void* ptr) noexcept;     // Array deallocator

void* Widget::operator new[](size_t size) {
  return malloc(size);
}

void Widget::operator delete[](void* ptr) noexcept {
  free(ptr);
}

// CRITICAL MISMATCH ERRORS:
Widget* p1 = new Widget[10];
delete p1;        // WRONG: Should be delete[], leaks memory + undefined behavior

Widget* p2 = new Widget;
delete[] p2;      // WRONG: Should be delete, reads invalid size metadata

// Modern C++ alternatives (safer):
std::vector<Widget> v(10);              // Automatic management
std::unique_ptr<Widget[]> pa(new Widget[10]);  // Smart pointer for arrays

