#include <iostream>
#include <cstdlib>

class Element {
    int id;
public:
    Element() : id(0) {
        std::cout << "Element default constructed\n";
    }

    explicit Element(int i) : id(i) {
        std::cout << "Element " << id << " constructed\n";
    }

    ~Element() {
        std::cout << "Element " << id << " destroyed\n";
    }

    void* operator new[](size_t size) {
        std::cout << "operator new[] called, size: " << size << " bytes\n";
        return malloc(size);
    }

    void operator delete[](void* ptr) noexcept {
        std::cout << "operator delete[] called\n";
        free(ptr);
    }
};

int main() {
    std::cout << "=== Correct: new[] with delete[] ===\n";
    Element* arr1 = new Element[3];  // Allocates + constructs 3 Elements
    delete[] arr1;                    // Destroys 3 Elements + deallocates

    std::cout << "\n=== Single object allocation ===\n";
    Element* single = new Element(99);
    delete single;  // NOT delete[] - single object

    std::cout << "\n=== WRONG EXAMPLE (commented to avoid crash) ===\n";
    Element* arr2 = new Element[5];
    // delete arr2;     // WRONG: Should be delete[]
    //                   // Only calls 1 destructor instead of 5
    //                   // Leaks memory for 4 elements
    //                   // May read invalid size metadata
    delete[] arr2;      // Correct

    Element* single2 = new Element(88);
    // delete[] single2;  // WRONG: Should be delete
    //                     // Reads garbage as array size
    //                     // May call destructor multiple times
    //                     // Causes undefined behavior
    delete single2;       // Correct

    return 0;
}
